import{_ as r,a0 as p,w as d,s as u,I as t,x as n,a1 as l,A as a,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"Linux Mint Debian Edition（LMDE） 5 – 完美穩定 | LCTT x X-CMD","titleTemplate":false,"description":"Linux Mint Debian Edition（LMDE） 5 – 完美穩定 | LCTT (202204) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux Mint Debian Edition（LMDE） 5 – 完美穩定 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux Mint Debian Edition（LMDE） 5 – 完美穩定 | LCTT (202204) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202204/20220325 Linux Mint Debian Edition 5 - Perfection with Stability -Review","title":"Linux Mint Debian Edition（LMDE） 5 – 完美穩定","tag":"202204","desc":""},"relativePath":"202204/20220325 Linux Mint Debian Edition 5 - Perfection with Stability -Review.md","filePath":"[post].md"}'),s={name:"202204/20220325 Linux Mint Debian Edition 5 - Perfection with Stability -Review.md"};function b(m,i,L,D,x,M){const e=p("Link");return d(),u("div",null,[i[24]||(i[24]=t("h1",{id:"linux-mint-debian-edition-lmde-5-–-完美穩定",tabindex:"-1"},[n("Linux Mint Debian Edition（LMDE） 5 – 完美穩定 "),t("a",{class:"header-anchor",href:"#linux-mint-debian-edition-lmde-5-–-完美穩定","aria-label":"Permalink to “Linux Mint Debian Edition（LMDE） 5 – 完美穩定”"},"​")],-1)),i[25]||(i[25]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202204/13/132621gz9v9c49k349ebe4.jpg",alt:""})],-1)),i[26]||(i[26]=t("blockquote",null,[t("p",null,"我們對最近發佈的 Linux Mint Debian Edition 5（LMDE 5）的性能、穩定性和用户友好性等方面進行了評測。這裏是我們的發現。")],-1)),t("p",null,[i[1]||(i[1]=n("在 Linux Mint Debian Edition LMDE 4（Debbie）發佈兩年多後，Linux Mint 團隊宣告了 Linux Mint Debian Edition LMDE 5（LMDE 5）的發佈。LMDE 5 基於 ",-1)),l(e,{href:"https://www.debugpoint.com/2021/05/debian-11-features/"},{default:a(()=>[...i[0]||(i[0]=[n("Debian 11 Bullseye",-1)])]),_:1}),i[2]||(i[2]=n(" ，它帶來了長期支持的 Linux 內核 5.10 和 Debian 軟件包源。除內核版本以外，大多數的應用程序和軟件包與 Linux Mint 20.3 幾乎完全相同。",-1))]),i[27]||(i[27]=o('<p>讓我們深入瞭解一下。</p><h3 id="lmde-5-評測" tabindex="-1">LMDE 5 評測 <a class="header-anchor" href="#lmde-5-評測" aria-label="Permalink to “LMDE 5 評測”">​</a></h3><p>我們測試 Linux Mint Debian Edition 5（LMDE 5）是在現有的較舊的硬件下：</p><ul><li>英特爾酷睿 i3 第一代</li><li>4GB DDR3 內存</li><li>博通芯片</li><li>英偉達® GeForce® 315M</li><li>固態硬盤</li></ul><h4 id="iso-下載、現場介質和安裝" tabindex="-1">ISO 下載、現場介質和安裝 <a class="header-anchor" href="#iso-下載、現場介質和安裝" aria-label="Permalink to “ISO 下載、現場介質和安裝”">​</a></h4><p>從新設計的 Linux Mint 網站找到並下載 ISO 文件是很容易的。<ruby>現場介質<rt>Live media</rt></ruby>啓動很順利，通過桌面上的安裝圖標啓動了安裝程序。</p>',6)),t("p",null,[i[4]||(i[4]=n("LMDE 使用的一款修改版的 Debian 安裝器。它不是 Calamares 。普通的 Debian 安裝器是很難操作的，[在我看來] 有點 ",-1)),l(e,{href:"https://www.debugpoint.com/2021/01/install-debian-buster/"},{default:a(()=>[...i[3]||(i[3]=[n("讓新用户感到困惑",-1)])]),_:1}),i[5]||(i[5]=n(" 。但是，Linux Mint 團隊使其非常容易安裝，只需幾個步驟，並從 Debian 安裝器中移除了所有使人困惑的選項。",-1))]),i[28]||(i[28]=o('<p>你只需要提供安裝位置、鍵盤佈局、名字和密碼，就可以開始安裝了。安裝器的分區系統使用 GParted ，它很方便好用。</p><p>因此，在我的測試的虛擬機和物理機硬件中，安裝過程都很順利。</p><p>在物理機系統中安裝花費了 4 到 5 分鐘，而虛擬機系統中的安裝時間約為 3 分鐘。</p><h4 id="第一印象" tabindex="-1">第一印象 <a class="header-anchor" href="#第一印象" aria-label="Permalink to “第一印象”">​</a></h4><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/03/Linux-Mint-Debian-Edition-5-LMDE5-Desktop-1024x580.jpg" alt="Linux Mint Debian Edition 5 LMDE5 Desktop"></p><p>如果你熟悉 Linux Mint 早期的 Cinnamon 桌面，那麼你不會在這個 Debian 版本中找到什麼不同。它們是一樣的。如果你是第一次使用 Linux Mint 的 Cinnamon 桌面環境，那麼在你完成你的安裝後，你會看到一個漂亮而乾淨的桌面。</p><p>桌面圖標、完美調整過的顏色和主題、底部任務欄、系統托盤，這一切都配合有序，讓你能夠立刻上手。</p><p>不管你使用低端還是高端的硬件，LMDE 都能快速響應，應用程序能夠很好的工作。應用程序的切換和整體桌面的響應都很可靠。</p><p>你得到的是經過良好測試的應用程序和軟件包，而基於 Debian 的穩定性，很少會出現故障。這意味着不必擔心軟件包的衝突、更新缺失，以及 Linux 系統的常見問題。</p><h4 id="預裝的應用程序" tabindex="-1">預裝的應用程序 <a class="header-anchor" href="#預裝的應用程序" aria-label="Permalink to “預裝的應用程序”">​</a></h4><p>Linux Mint（不僅僅是 Debian 版本）的優勢之一是它的預裝的應用程序。許多 Linux 發行版由於 ISO 大小等原因，在 ISO 安裝程序中不包括必要的應用程序。</p><p>但是，Linux Mint 團隊全心全意為它們的用户考慮，打包了所有你需要的必要應用程序。這照顧到了大多數用户的需求。它有助於減少最終用户在安裝 LMDE 5 後搜索和安裝兼容應用程序方面的負擔。</p><p>例如，在 LMDE 5 中，已默認安裝下面的必備軟件，隨時待用：</p><ul><li>繪圖應用</li><li>多媒體：Celluloid 媒體播放器、Hypnotix、Rythmbox</li><li>Torrent 客户端：Transmission 3.0</li><li>完整的辦公套件：LibreOffice 7.0</li><li>Email 客户端：Thunderbird 91.0</li><li>網頁瀏覽器：Firefox 97.0</li></ul><p>這不是所有。對於下面的所有的具體使用情況，你都會得到一個專門的原生應用程序。用户不需要為這些尋找一個單獨的應用程序：</p><ul><li>屏幕截圖和屏幕保護程序</li><li>減少眼睛疲勞的工具</li><li>USB 格式化工具和鏡像寫入器</li><li>便籤</li><li>Synaptic 軟件包管理器</li><li>系統備份和恢復</li><li>防火牆工具</li></ul><h4 id="lmde5-的性能表現怎麼樣" tabindex="-1">LMDE5 的性能表現怎麼樣? <a class="header-anchor" href="#lmde5-的性能表現怎麼樣" aria-label="Permalink to “LMDE5 的性能表現怎麼樣?”">​</a></h4><p>看到一個發行版按照預期的表現，總是令人感興趣的。而 LMDE 5 的性能表現遠超預期。</p><p>在空閒狀態下，它消耗 750 MB 的內存和 2% 的 CPU 。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/03/Performance-During-light-workload-1024x606.jpg" alt="Performance During the light workload"></p><p>接下來，我使用下面的任務讓它完成繁重的工作負載：</p><ul><li>Firefox（打開三個標籤頁，其中一個播放 YouTube 視頻）</li><li>LibreOffice Calc（打開一個表格）</li><li>繪圖應用程序（打開一個實例）</li><li>設置</li><li>一個終端窗口</li><li>文件管理器</li></ul><p>在上述的工作負載中，它消耗了大約 1.5 GB 的內存和 14% 的 CPU 。顯然，大部分的資源都被 Firefox 消耗了。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/03/Performance-During-heavy-workload-1024x601.jpg" alt="Performance During heavy workload"></p><p>在我看來，這是一個完美的指標，而且對舊硬件進行了很好的優化分配。上述指標是在物理機系統上測量的。</p><h4 id="連接性" tabindex="-1">連接性 <a class="header-anchor" href="#連接性" aria-label="Permalink to “連接性”">​</a></h4><p>連接性是任何操作系統的不可或缺的一部分。LMDE 5 能夠連接到 Wi-Fi（使用一款老舊的博通芯片）和連接到藍牙音箱，而不需任意的額外調整。</p><p>在我的測試期間，音量控制與藍牙守護進程配合得很好。</p><p>此外，我們也測試了 USB 接口設備的熱插拔，它們可以自動偵測和掛載，而沒有遇到任何問題。</p><p>所以，沒有什麼意外，這也是意料之中的。</p><h3 id="有什麼錯誤嗎" tabindex="-1">有什麼錯誤嗎？ <a class="header-anchor" href="#有什麼錯誤嗎" aria-label="Permalink to “有什麼錯誤嗎？”">​</a></h3><p>我在測試期間沒有遇到任何錯誤。一切都運行良好。</p><p>但是當我關閉我的物理測試系統的筆記本蓋板時，我發現一個錯誤。在它進入待機狀態後，不能將其喚醒。我無法看到登錄屏幕，屏幕是黑色的，沒有任何光標。我必須因重啓才能進入系統。</p><p>這可能是我測試設備上的特定硬件設備的問題。我相信它在新的硬件系統上不會有任何的問題。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>總結一下 LMDE 5 的評測，它顯然是最穩定、最優化的 Linux 發行版。如果你計劃在未來兩年或更長的時間段內使用一款用於日常用途的系統，你可以信賴這個版本。因此，如果你需要一款非基於 Ubuntu 的穩定的、快速的、低維護率的長期日用系統，並運行在你的舊機器或新機器上，這會是一個完美的選擇。請試試。</p>',36)),t("p",null,[i[7]||(i[7]=n("你可以 ",-1)),l(e,{href:"https://linuxmint.com/edition.php?id=297"},{default:a(()=>[...i[6]||(i[6]=[n("在官方網站上",-1)])]),_:1}),i[8]||(i[8]=n(" 下載 LMDE 5 。",-1))]),i[29]||(i[29]=t("p",null,"感謝閲讀。",-1)),i[30]||(i[30]=t("hr",null,null,-1)),t("p",null,[i[10]||(i[10]=n("via: ",-1)),l(e,{href:"https://www.debugpoint.com/2022/03/linux-mint-debian-edition-5-review/"},{default:a(()=>[...i[9]||(i[9]=[n("https://www.debugpoint.com/2022/03/linux-mint-debian-edition-5-review/",-1)])]),_:1})]),t("p",null,[i[15]||(i[15]=n("作者：",-1)),l(e,{href:"https://www.debugpoint.com/author/admin1/"},{default:a(()=>[...i[11]||(i[11]=[n("Arindam",-1)])]),_:1}),i[16]||(i[16]=n(" 選題：",-1)),l(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...i[12]||(i[12]=[n("lujun9972",-1)])]),_:1}),i[17]||(i[17]=n(" 譯者：",-1)),l(e,{href:"https://github.com/robsean"},{default:a(()=>[...i[13]||(i[13]=[n("robsean",-1)])]),_:1}),i[18]||(i[18]=n(" 校對：",-1)),l(e,{href:"https://github.com/wxy"},{default:a(()=>[...i[14]||(i[14]=[n("wxy",-1)])]),_:1})]),t("p",null,[i[21]||(i[21]=n("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[19]||(i[19]=[n("LCTT",-1)])]),_:1}),i[22]||(i[22]=n(" 原創編譯，",-1)),l(e,{href:"https://linux.cn/"},{default:a(()=>[...i[20]||(i[20]=[n("Linux中國",-1)])]),_:1}),i[23]||(i[23]=n(" 榮譽推出",-1))])])}const g=r(s,[["render",b]]);export{w as __pageData,g as default};
